public class METSalesInvoiceDataGenerator
{
    MetShipmentId       shipmentId;
    Str1260             bundlingHeaderGUID;

    Map                             salesUnitTextMap;
    Map                             itemTypeDescCache;
    Map                             uomConversionCache;

    Map                             taxByInventTransId;
    Map                             componentSums;

    Map                             markupTransByInventTransId;
    Map                             licenceCustTobaccoMap;
    Map                             licenceCustLiqMap;
    Map                             licenceMetcashMap;
    Map                             markupCalcAmountOnly;
    Map                             Fees;
    Map                             headerTaxTrans;

    LogisticsElectronicAddressLocator invoiceToPhone, shipToPhone;

    CustFormLetterParameters        custFormLetterParameters;
    CompanyInfo                     companyInfo;
    InventLocation                  inventLocation;

    RecordInsertList                bundleSalesInvoiceHeaderFooterList;
    RecordInsertList                bundleSalesCTInvoiceList;
    RecordInsertList                bundleSalesInvoiceList;

    LanguageId                  languageIdUser;

    LogisticsElectronicAddressLocator remitEmail;


    EcoResProductParameters     ecoResProductParameters;

}

Method.Source:
void new(MetShipmentId  _shipmentId, Str1260  _bundlingHeaderGUID)
{
    shipmentId = _shipmentId;
    bundlingHeaderGUID = _bundlingHeaderGUID;
}

public void generateHeaderKPMGFields(METBundleSalesInvoiceHeaderFooterTmp bundlingHeaderFooterTmp, CustInvoiceJour  _custInvoiceJour)
{
    CustInvoiceJour custInvoiceJour;
    MarkupTrans markupTrans;

    #define.Admin('Admin')

    while select MarkupCode, CalculatedAmount, MarkupCategory, Value, METChargesMethod, METAdvancedCalculation, ModuleType, Txt from markupTrans
    where markupTrans.TransTableId == _custInvoiceJour.TableId &&
      markupTrans.TransRecId == _custInvoiceJour.RecId &&
      markupTrans.CalculatedAmount != 0
    {
        MarkupAutoLine markupAutoLine;
        MarkupAutoTable markupAutoTable;

        if (markupTrans.METAdvancedCalculation)
        {
            select firstOnly Description from markupAutoTable
        where markupAutoTable.METAdvancedCalculation == NoYes::Yes
    exists join markupAutoLine
        where markupAutoLine.TableRecId == markupAutoTable.RecId
          && markupAutoLine.TableTableId == markupAutoTable.TableId
          && markupAutoLine.METChargesMethod == markupTrans.METChargesMethod
          && markupAutoLine.Value == markupTrans.Value
          && markupAutoLine.MarkupCode == markupTrans.MarkupCode;
        }
        else
        {
            select firstOnly Description from markupAutoTable
        where markupAutoTable.METAdvancedCalculation == NoYes::No
    exists join markupAutoLine
        where markupAutoLine.TableRecId == markupAutoTable.RecId
          && markupAutoLine.TableTableId == markupAutoTable.TableId
          && markupAutoLine.MarkupCategory == markupTrans.MarkupCategory
          && markupAutoLine.Value == markupTrans.Value
          && markupAutoLine.MarkupCode == markupTrans.MarkupCode;
        }

        if (!markupAutoTable.Description)
        {
            if (markupTrans.MarkupCode == METConstants::MDF)
            {
                markupAutoTable.Description = METConstants::MDFDesc;
            }
            else if (markupTrans.markuptable().Txt)
            {
                markupAutoTable.Description = markupTrans.markuptable().Txt;
            }
            else
            {
                markupAutoTable.Description = markupTrans.Txt;
            }
        }

        // Lasernet change request - show all markups including
        bundlingHeaderFooterTmp.KPMGHeaderCharges += markupAutoTable.Description +  ' ' +  num2str(markupTrans.Value, 0, 3, 1, 0) + '\n';

        if (markupTrans.MarkupCode == #Admin)
        {
            bundlingHeaderFooterTmp.METAdminFeeSymbol = (markupTrans.MarkupCategory == MarkupCategory::Fixed) ? METConstants::Dollar : METConstants::Percent;
        }

        TaxTrans taxTransBuf;

        select sum(SourceTaxAmountCur) from taxTransBuf
            where markupTrans.RecId == taxTransBuf.SourceRecId && markupTrans.TableId == taxTransBuf.SourceTableId
             && taxTransBuf.SourceTaxAmountCur != 0;

        if (taxTransBuf.SourceTaxAmountCur)
        {
            Amount  gstExclValue        = markupTrans.CalculatedAmount + abs(taxTransBuf.SourceTaxAmountCur);

            bundlingHeaderFooterTmp.KPMGHeaderChargesValue          += strFmt('%1', gstExclValue) + '\n';
            bundlingHeaderFooterTmp.METHeaderLineGSTValue           += strFmt('%1',abs(taxTransBuf.SourceTaxAmountCur)) + '\n';//GST
            bundlingHeaderFooterTmp.METHeaderLineTotExclGSTValue    += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
        }
        else
        {
            bundlingHeaderFooterTmp.METHeaderLineGSTValue += strFmt('%1', 0.00) + '\n';
            bundlingHeaderFooterTmp.METHeaderLineTotExclGSTValue  += strFmt('%1',0.00) + '\n';

            // For return sales type, the value should be shown as negative in invoice.
            bundlingHeaderFooterTmp.KPMGHeaderChargesValue          += strFmt('%1',markupTrans.CalculatedAmount) + '\n';

        }
    }
}

public void generateHeaderChangesFee()
{
    CustInvoiceJour custInvoiceJour;
    MarkupTrans     markupTrans;
    SalesTable      salesTable;

    TaxTrans        taxTrans;

    Fees = new Map(Types::String,Types::Real);
    headerTaxTrans = new Map(Types::String,Types::Real);
    str key;

    while select sum(CalculatedAmount), TransTableId, TransRecId from markupTrans
        group by markupTrans.TransTableId, markupTrans.TransRecId
       exists join custInvoiceJour
            where custInvoiceJour.METShipmentId == shipmentId &&
                  custInvoiceJour.TableId == markupTrans.TransTableId &&
                  custInvoiceJour.RecId == markupTrans.TransRecId
            exists join salesTable
                where salesTable.SalesId == custInvoiceJour.SalesId &&
                      !(salesTable.METInvoiceType == METInvoiceTypeSO::ChargeThroughClaim ||
                       salesTable.METInvoiceType == METInvoiceTypeSO::CrossDockClaim)
    {
        key = strFmt("%1|%2", markupTrans.TransTableId, markupTrans.TransRecId);

        if (!Fees.exists(markupTrans))
        {
            Fees.insert(key, markupTrans.CalculatedAmount);
        }
    }


    while select sum(SourceRegulateAmountCur), Voucher from taxTrans
         group by taxTrans.Voucher
        where taxTrans.InventTransId == ''
        exists join custInvoiceJour
            where custInvoiceJour.METShipmentId == shipmentId &&
                  custInvoiceJour.LedgerVoucher == taxTrans.Voucher &&
                  custInvoiceJour.InvoiceDate == taxTrans.TransDate
    {
        if (!headerTaxTrans.exists(taxTrans.Voucher))
        {
            headerTaxTrans.insert(taxTrans.Voucher, taxTrans.SourceRegulateAmountCur);
        }
    }


}

public void setShipInvoicePhone()
{
    DirPartyLocation                    dirPartyLocation;
    LogisticsElectronicAddress          logisticsElectronicAddress;
    LogisticsElectronicAddressRole      logisticsElectronicAddressRole;
    LogisticsLocationRole               logisticsLocationRole;

    CustTable                           custTable = CustTable::find(METSalesOrderShipmentLoadHeader::findByShipmentId(shipmentId).CustAccount);

    select firstonly Locator from logisticsElectronicAddress
        where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
        exists join dirPartyLocation
            where dirPartyLocation.Location == logisticsElectronicAddress.Location &&
                dirPartyLocation.Party == custTable.Party
        exists join logisticsElectronicAddressRole
            where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
        exists join logisticsLocationRole
            where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
            && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Invoice);

    invoiceToPhone = logisticsElectronicAddress.Locator;

    select firstonly Locator from logisticsElectronicAddress
        where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
        exists join dirPartyLocation
            where dirPartyLocation.Location == logisticsElectronicAddress.Location&&
                dirPartyLocation.Party == custTable.Party
        exists join logisticsElectronicAddressRole
            where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
        exists join logisticsLocationRole
            where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
            && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Delivery);

    shipToPhone = logisticsElectronicAddress.Locator;
}

public static METSalesInvoiceDataGenerator construct(MetShipmentId  _shipmentId, Str1260  _bundlingHeaderGUID)
{
    return new METSalesInvoiceDataGenerator(_shipmentId, _bundlingHeaderGUID);
}

public void generateLicenceCache()
{
    METCustomerLicence  metCustomerLicenceTobacco, metCustomerLicenceLiquor;
    METMetcashLicence   metMetcashLicenceTobacco;
    METSalesOrderShipmentLoadHeader shipmentLoadHeader;
    METSalesOrderShipmentLoadLines  orderLines;
    METInventItemOrderSetup inventItemOrderSetup;

    licenceCustLiqMap     = new Map(Types::String, Types::String);
    licenceCustTobaccoMap = new Map(Types::String, Types::String);
    licenceMetcashMap     = new Map(Types::String, Types::String);

    shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByShipmentId(shipmentId);
    if (!shipmentLoadHeader)
    {
        return;
    }

    select firstonly LicenceNumber from metCustomerLicenceLiquor
        where metCustomerLicenceLiquor.CustAccount == shipmentLoadHeader.CustAccount
           && metCustomerLicenceLiquor.Type        == METLicenceType::Liquor;

    select firstonly LicenceNumber from metCustomerLicenceTobacco
        where metCustomerLicenceTobacco.CustAccount == shipmentLoadHeader.CustAccount
           && metCustomerLicenceTobacco.Type        == METLicenceType::Tobacco;

    select firstonly LicenceNumber from metMetcashLicenceTobacco
        where metMetcashLicenceTobacco.InventSiteId == shipmentLoadHeader.SiteId
           && metMetcashLicenceTobacco.Type         == METLicenceType::Tobacco;

    if (!metCustomerLicenceLiquor.LicenceNumber
     && !metCustomerLicenceTobacco.LicenceNumber
     && !metMetcashLicenceTobacco.LicenceNumber)
    {
        return;
    }

    if (metCustomerLicenceLiquor.LicenceNumber)
    {
        while select OrderNum from orderLines
            group by orderLines.OrderNum
            where orderLines.ShipmentId == shipmentId
        {
            licenceCustLiqMap.insert(orderLines.OrderNum, metCustomerLicenceLiquor.LicenceNumber);
        }
    }

    if (metCustomerLicenceTobacco.LicenceNumber || metMetcashLicenceTobacco.LicenceNumber)
    {
        while select OrderNum from orderLines
            group by orderLines.OrderNum
            where orderLines.ShipmentId == shipmentId
            exists join inventItemOrderSetup
                where inventItemOrderSetup.SiteId   == shipmentLoadHeader.SiteId
                   && inventItemOrderSetup.ItemId   == orderLines.ItemId
                   && inventItemOrderSetup.ItemType == METConstants::T
        {
            if (metCustomerLicenceTobacco.LicenceNumber)
            {
                licenceCustTobaccoMap.insert(orderLines.OrderNum, metCustomerLicenceTobacco.LicenceNumber);
            }
            if (metMetcashLicenceTobacco.LicenceNumber)
            {
                licenceMetcashMap.insert(orderLines.OrderNum, metMetcashLicenceTobacco.LicenceNumber);
            }
        }
    }
}

public void generateSalesInvoiceData(METBundleSalesInvoiceHeaderFooterTmp bundlingHeaderFooterTmp, METBundleSalesInvoiceTmp bundleSalesInvoiceTmp, METBundleSalesCTInvoiceTmp metSalesCTInvoiceTmp)
{
    CustInvoiceJour         custInvoiceJour;
    CustInvoiceTrans        custInvoiceTrans;
    CustTable               custTable;
    METCustTable            metCustTable;
    SalesTable              salesTable;
    METSalesTable           metSalesTable;
    METIndustryKeyTable     metIndustryKeyTable;
    METCustomerLicence      metCustomerLicenceTobacco, metCustomerLicenceLiquor;
    METMetcashLicence       metMetcashLicenceTobacco;
    METInventItemOrderSetup metInventItemOrderSetup;
    DirPartyTable           dirPartyTable;
    METSalesOrderTypes      metSalesOrderTypes;
    METWHSPhysDimUOMSite    whsPhysDimUOMSite;
    SalesLine               salesLine;
    TaxTrans                taxTrans;
    METInventTable          metInventTable;

    companyInfo = CompanyInfo::find();
    custFormLetterParameters = CustFormLetterParameters::find();
    ecoResProductParameters = EcoResProductParameters::find();

    this.generateCachedTaxTransComponents();
    this.generateCachedLinePricingComponents();
    this.generateCachedMarkupTrans();
    this.generateLicenceCache();
    this.setShipInvoicePhone();
    this.generateHeaderChangesFee();

    InvoiceId lastInvoiceId;

    remitEmail = this.getRemitEmail();

    languageIdUser = SysUserInfo::find(curUserId()).Language;

    Str1260 headerGuid;

    bundleSalesInvoiceList = new RecordInsertList(tableNum(METBundleSalesInvoiceTmp), true, true, true, true, true, bundleSalesInvoiceTmp);

    bundleSalesInvoiceHeaderFooterList = new RecordInsertList(tableNum(METBundleSalesInvoiceHeaderFooterTmp), true, true, true, true, true, bundlingHeaderFooterTmp);

    bundleSalesCTInvoiceList = new RecordInsertList(tableNum(METBundleSalesCTInvoiceTmp), true, true, true, true, true, metSalesCTInvoiceTmp);

    while select custInvoiceTrans
        order by custInvoiceTrans.InvoiceId, custInvoiceTrans.SalesId, custInvoiceTrans.LineNum
        join salesLine
            where salesLine.InventTransId == custInvoiceTrans.InventTransId
        join AlcoholContent, CountryCode, ItemSize from metInventTable
            where metInventTable.ItemId == custInvoiceTrans.ItemId
        join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
        join SalesId, InventLocationId, METSalesOrderType, InventSiteId, SalesType, METRoute,
             METRouteStopNum, Payment, VATNum, CustAccount, ReturnItemNum from salesTable
            where salesTable.SalesId == custInvoiceJour.SalesId
        join SalesId, DeliveryInstructions, OriginalInvoice, SalesTable from metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId
        join RecId, Name from inventLocation
            where inventLocation.InventLocationId == salesTable.InventLocationId
        join AccountNum, Party, CustGroup, METCustOperGroupId from custTable
            where custTable.AccountNum == custInvoiceJour.InvoiceAccount
        join Name, NameAlias, KnownAs from dirPartyTable
            where dirPartyTable.RecId == custTable.Party
        join AccountNum, IndustryKey, BPayReference, BPayBillerCode, SalesRepCode, BsbReference from metCustTable
            where metCustTable.AccountNum == custTable.AccountNum
        join IndustryKey, ParentIndustryKey, CompanyName from metIndustryKeyTable
            where metIndustryKeyTable.IndustryKey == metCustTable.IndustryKey
        outer join SalesInvoiceReportDesignName from metSalesOrderTypes
            where metSalesOrderTypes.SalesOrderTypeID == salesTable.METSalesOrderType
        outer join NetWeight from whsPhysDimUOMSite
            where whsPhysDimUOMSite.ItemId == salesLine.ItemId
               && whsPhysDimUOMSite.UOM == salesLine.SalesUnit
               && whsPhysDimUOMSite.SiteId == inventLocation.InventSiteId
        outer join ItemType from metInventItemOrderSetup
            where metInventItemOrderSetup.SiteId == salesTable.InventSiteId &&
                  metInventItemOrderSetup.ItemId == custInvoiceTrans.ItemId
    {
        if (custInvoiceTrans.InvoiceId != lastInvoiceId)
        {
            lastInvoiceId = custInvoiceTrans.InvoiceId;
            headerGuid = guid2Str(newGuid());
            this.generateBundlingHeaderFooterTmp(custInvoiceJour, custTable, metCustTable, salesTable, metSalesTable,metIndustryKeyTable, dirPartyTable, metInventItemOrderSetup, metSalesOrderTypes, headerGuid, bundlingHeaderFooterTmp, metSalesCTInvoiceTmp);
        }

        this.generateSalesInvoiceTmp(custInvoiceJour, custInvoiceTrans, salesLine, metSalesOrderTypes, metIndustryKeyTable, whsPhysDimUOMSite, metInventItemOrderSetup, metInventTable, salesTable, metSalesTable,headerGuid, bundleSalesInvoiceTmp);
    }

    bundleSalesInvoiceHeaderFooterList.insertDatabase();
    bundleSalesCTInvoiceList.insertDatabase();
    bundleSalesInvoiceList.insertDatabase();
}

private real getCachedConversion(ItemId _itemId, UnitOfMeasureSymbol _from, UnitOfMeasureSymbol _to)
{
    if (!uomConversionCache)
    {
        uomConversionCache = new Map(Types::String, Types::Real);
    }
    str key = strFmt('%1|%2|%3', _itemId, _from, _to);

    if (!uomConversionCache.exists(key))
    {
        RecId fromUom = UnitOfMeasure::unitOfMeasureIdBySymbol(_from);
        RecId toUom   = UnitOfMeasure::unitOfMeasureIdBySymbol(_to);

        RecId product = InventTable::itemProduct(_itemId);
        real val = UnitOfMeasureConverter::canBeConverted(fromUom, toUom, product)

        ? UnitOfMeasureConverter::convert(1, fromUom, toUom, NoYes::No, product, NoYes::No)
        : 1;

        uomConversionCache.insert(key, val);
    }

    return uomConversionCache.lookup(key);
}

public SysDocuBrandDetails findByRepNameIndKeyandDesignName(SrsReportName _repName, SRSReportDesignName _designName, METIndustryKey _indKey)
{
    SysDocuBrandDetails sysDocuBrandDetails;

    if (_repName && _designName && _indKey)
    {
        select firstonly sysDocuBrandDetails
            where sysDocuBrandDetails.ReportName == _repName
            && sysDocuBrandDetails.DesignName == _designName
            && sysDocuBrandDetails.METIndustryKey == _indKey;
    }
    else
    {
        select firstonly sysDocuBrandDetails
            where sysDocuBrandDetails.ReportName == _repName
            && sysDocuBrandDetails.DesignName == METIndustryKeyTable::find(_indKey).ParentIndustryKey
            && sysDocuBrandDetails.METIndustryKey == _indKey;
    }
    return sysDocuBrandDetails;
}

protected UnitOfMeasureReportingText getSalesUnitText(SalesUnit _salesUnit, LanguageId _languageId)
{
    if (!salesUnitTextMap)
    {
        salesUnitTextMap = new Map(Types::String, Types::String);
    }

    str salesUnitTextKey = strFmt('%1.%2', _salesUnit, _languageId);

    UnitOfMeasureReportingText salesUnitText;

    if (salesUnitTextMap.exists(salesUnitTextKey))
    {
        salesUnitText = salesUnitTextMap.lookup(salesUnitTextKey);
    }
    else
    {
        salesUnitText = UnitOfMeasureReportingTranslation::unitOfMeasureReportingText(
        UnitOfMeasure::unitOfMeasureIdBySymbol(_salesUnit),
        _languageId);

        salesUnitTextMap.insert(salesUnitTextKey, salesUnitText);
    }

    return salesUnitText;
}

public AttributeValueText metGetProductAttributeforInvCategory(ItemId _itemID)
{
    InventTable                 inventTable = InventTable::find(_itemID);
    METGetAttributeValue        getAttributeValue;
    AttributeValueText          productAttributeforCategory;

    if (inventTable.RecId
            && ecoResProductParameters.METInvoiceCategory)
    {
        getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
        productAttributeforCategory = getAttributeValue.getAttributeValue(ecoResProductParameters.METInvoiceCategory);
    }

    return  productAttributeforCategory;
}

public Amount getLinecharges(CustInvoiceTrans _custInvoiceTrans, SalesLine _salesLine)
{
    METSalesLinePriceComponent metSalesLinePriceComponent;
    METComponentCode           metComponentCode;

    select sum(Value) from metSalesLinePriceComponent
        where metSalesLinePriceComponent.InventTransId == _custInvoiceTrans.InventTransId
        join metComponentCode
            where metComponentCode.Component == metSalesLinePriceComponent.Component
               && metComponentCode.IncludeInRebatesOrFees == NoYes::Yes
               && metComponentCode.Component != METConstants::excise
               && metComponentCode.Component != METConstants::pickFee
               && metComponentCode.PriceComponent == METPriceComponent::LineCharges;

    return metSalesLinePriceComponent.Value;
}

public Amount getconversionValueforEA(CustInvoiceTrans _custInvoiceTrans)
{
    InventItemSalesSetup inventItemSalesSetup;
    Inventdim inventdim;
    Real convertedValue = 1;

    select METSalesUnit from inventItemSalesSetup
     exists join inventdim where inventdim.inventdimid == inventItemSalesSetup.INVENTDIMID
         && inventItemSalesSetup.itemid == _custInvoiceTrans.ItemId && inventdim.InventSiteId == _custInvoiceTrans.inventSiteId();

    if (_custInvoiceTrans.SalesUnit == METConstants::unitEach)
    {
        convertedValue =  this.getCachedConversion(_custInvoiceTrans.ItemId, inventItemSalesSetup.METSalesUnit, _custInvoiceTrans.SalesUnit);
    }

    return convertedValue;
}

private Description getItemTypeDescription(METItemTypes _itemType)
{
    if (!itemTypeDescCache)
    {
        itemTypeDescCache = new Map(Types::String, Types::String);
    }
    if (!itemTypeDescCache.exists(_itemType))
    {
        itemTypeDescCache.insert(_itemType, METItemType::find(_itemType).Description);
    }
    return itemTypeDescCache.lookup(_itemType);
}

public Map generateCachedTaxTransComponents()
{
    CustInvoiceTrans    custInvoiceTrans;
    CustInvoiceJour     custInvoiceJour;
    TaxTrans            taxTrans;

    InventTransId       lastInventTransId;

    taxByInventTransId = new Map(Types::String, Types::Container);

    Map taxByCode = new Map(Types::String, Types::Real);

    TaxValue taxValuePct;

    while select sum(SourceTaxAmountCur), TaxCode, TaxGroup, TaxValue, InventTransId from taxTrans
        group by taxTrans.InventTransId, taxTrans.TaxCode, taxTrans.TaxGroup, taxTrans.TaxValue
        order by taxTrans.InventTransId
    exists join custInvoiceTrans
        where custInvoiceTrans.InventTransId == taxTrans.InventTransId
    exists join custInvoiceJour
        where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                custInvoiceJour.METShipmentId == shipmentId
    {
        // Incident 424568: WILO - Demand - WET and GST Flags and $ values incorrect on some items on PDF INV - ALM
        // To avoid going in if (lastInventTransId != taxTrans.InventTransId) the first iteration of the loop
        if (!lastInventTransId)
        {
            lastInventTransId = taxTrans.InventTransId;
        }

        if (lastInventTransId != taxTrans.InventTransId)
        {
            taxByInventTransId.insert(lastInventTransId, [taxByCode.pack(), taxValuePct]);
            taxByCode           = new Map(Types::String, Types::Real);
            taxValuePct         = 0;
            lastInventTransId   = taxTrans.InventTransId;
        }

        if (!taxValuePct && taxTrans.TaxValue)
        {
            taxValuePct = taxTrans.TaxValue;
        }

        real prev = taxByCode.exists(taxTrans.TaxCode) ? taxByCode.lookup(taxTrans.TaxCode) : 0;
        taxByCode.insert(taxTrans.TaxCode, prev + taxTrans.SourceTaxAmountCur);                 
    }

    // Incident 424568: WILO - Demand - WET and GST Flags and $ values incorrect on some items on PDF INV - ALM
    // For the last InventTransId
    if (taxByCode.elements())
    {
        taxByInventTransId.insert(lastInventTransId, [taxByCode.pack(), taxValuePct]);
    }

    return taxByInventTransId;
}

public Map generateCachedLinePricingComponents()
{
    componentSums = new Map(Types::String, Types::Real);
    CustInvoiceJour custInvoiceJour;
    CustInvoiceTrans custInvoiceTrans;
    str key;

    METSalesLinePriceComponent salesLinePriceComponentDeliveryFee;

    while select sum(Value), InventTransId from salesLinePriceComponentDeliveryFee
        group by salesLinePriceComponentDeliveryFee.InventTransId
        where salesLinePriceComponentDeliveryFee.Component == METConstants::DeliveryFee
        exists join custInvoiceTrans
            where custInvoiceTrans.InventTransId == salesLinePriceComponentDeliveryFee.InventTransId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
    {
        key = strFmt("%1|%2",METConstants::DeliveryFee, salesLinePriceComponentDeliveryFee.InventTransId);

        if (!componentSums.exists(key))
        {
            componentSums.insert(key , salesLinePriceComponentDeliveryFee.Value);
        }
    }

    METSalesLinePriceComponent salesLinePriceComponentBrokenCase;

    while select sum(Value), InventTransId from salesLinePriceComponentBrokenCase
        group by salesLinePriceComponentBrokenCase.InventTransId
        where salesLinePriceComponentBrokenCase.Component == METConstants::brokenCaseFee
        exists join custInvoiceTrans
            where custInvoiceTrans.InventTransId == salesLinePriceComponentBrokenCase.InventTransId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
    {
        key = strFmt("%1|%2",METConstants::brokenCaseFee, salesLinePriceComponentBrokenCase.InventTransId);

        if (!componentSums.exists(key))
        {
            componentSums.insert(key , salesLinePriceComponentBrokenCase.Value);
        }
    }

    METSalesLinePriceComponent salesLinePriceComponentBasePrice;
    METComponentCode metComponentCode;

    while select sum(Value), InventTransId from salesLinePriceComponentBasePrice
        group by salesLinePriceComponentBasePrice.InventTransId
        exists join metComponentCode
            where metComponentCode.Component == salesLinePriceComponentBasePrice.Component &&
                  metComponentCode.PriceComponent == METPriceComponent::BasePrice
        exists join custInvoiceTrans
            where custInvoiceTrans.InventTransId == salesLinePriceComponentBasePrice.InventTransId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
    {
        key = strFmt("%1|%2",METConstants::ComponentBasePrice, salesLinePriceComponentBasePrice.InventTransId);

        if (!componentSums.exists(key))
        {
            componentSums.insert(key , salesLinePriceComponentBasePrice.Value);
        }
    }

    METSalesLinePriceComponent salesLinePriceComponentMargin;

    while select sum(Value), InventTransId from salesLinePriceComponentMargin
        group by salesLinePriceComponentMargin.InventTransId
        exists join metComponentCode
            where metComponentCode.Component == salesLinePriceComponentMargin.Component &&
                  metComponentCode.PriceComponent == METPriceComponent::Margins
        exists join custInvoiceTrans
            where custInvoiceTrans.InventTransId == salesLinePriceComponentMargin.InventTransId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
    {
        key = strFmt("%1|%2",METConstants::ComponentMargin, salesLinePriceComponentMargin.InventTransId);

        if (!componentSums.exists(key))
        {
            componentSums.insert(key , salesLinePriceComponentMargin.Value);
        }
    }

    METSalesLinePriceComponent salesLinePriceComponentDiscount;

    while select sum(Value), InventTransId from salesLinePriceComponentDiscount
        group by salesLinePriceComponentDiscount.InventTransId
        exists join metComponentCode
            where metComponentCode.Component == salesLinePriceComponentDiscount.Component &&
                  metComponentCode.PriceComponent == METPriceComponent::Discounts
        exists join custInvoiceTrans
            where custInvoiceTrans.InventTransId == salesLinePriceComponentDiscount.InventTransId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId
    {
        key = strFmt("%1|%2",METConstants::ComponentDiscount, salesLinePriceComponentDiscount.InventTransId);

        if (!componentSums.exists(key))
        {
            componentSums.insert(key , salesLinePriceComponentDiscount.Value);
        }
    }

    return componentSums;
}

public void generateSalesInvoiceTmp(CustInvoiceJour             _custInvoiceJour,
                                    CustInvoiceTrans            _custInvoiceTrans,
                                    SalesLine                   salesLine,
                                    METSalesOrderTypes          metSalesOrderTypes,
                                    METIndustryKeyTable         metIndustryKeyTable,
                                    METWHSPhysDimUOMSite        metWHSPhysDimUOMSite,
                                    METInventItemOrderSetup     metInventItemOrderSetup,
                                    METInventTable              metInventTable,
                                    SalesTable                  salesTable,
                                    METSalesTable               metSalesTable,
                                    str1260                     headerGuid,
                                    METBundleSalesInvoiceTmp    bundleSalesInvoiceTmp)
{

    bundleSalesInvoiceTmp.clear();
    bundleSalesInvoiceTmp.BundleReportHeaderGuidStr = bundlingHeaderGUID;
    bundleSalesInvoiceTmp.SalesInvoiceHeaderGuidStr = headerGuid;
    bundleSalesInvoiceTmp.InvoiceId               = _custInvoiceJour.InvoiceId;
    bundleSalesInvoiceTmp.ItemId                  = _custInvoiceTrans.ItemId;
    bundleSalesInvoiceTmp.Name                    = _custInvoiceTrans.Name;
    bundleSalesInvoiceTmp.SalesUnitTxt            = this.getSalesUnitText(_custInvoiceTrans.SalesUnit, _custInvoiceJour.LanguageId);
    bundleSalesInvoiceTmp.Qty                     = _custInvoiceTrans.Qty;
    bundleSalesInvoiceTmp.LineAmount              = _custInvoiceTrans.LineAmount;

    bundleSalesInvoiceTmp.METINDS                 =   salesLine.getSalesLineInvoiceIndicator(true);

    //bundleSalesInvoiceTmp.MarkupCode      = metMarkupTransStd.MarkupCode;
    str calcAmtCacheKey = strFmt("%1|%2", _custInvoiceTrans.TableId, _custInvoiceTrans.RecId);
    bundleSalesInvoiceTmp.MarkupAmount    = markupCalcAmountOnly.exists(calcAmtCacheKey) ? markupCalcAmountOnly.lookup(calcAmtCacheKey) : 0;
    bundleSalesInvoiceTmp.METRetailAmount = bundleSalesInvoiceTmp.LineAmount;

    container taxComponents = taxByInventTransId.exists(_custInvoiceTrans.InventTransId) ? taxByInventTransId.lookup(_custInvoiceTrans.InventTransId) : conNull();
    Map taxByCode;
    Amount gstAmt;
    Amount wegAmt;
    Amount wetAmt;

    // Add condition is the map is null ignore below code to execute
    if (conLen(taxComponents) > 0)
    {
        taxByCode = Map::create(conPeek(taxComponents, 1));

        bundleSalesInvoiceTmp.METTaxPercent = conPeek(taxComponents, 2);

        gstAmt = taxByCode.exists(METConstants::GST) ? abs(taxByCode.lookup(METConstants::GST)) : 0;
        wegAmt = taxByCode.exists(METConstants::WEG) ? abs(taxByCode.lookup(METConstants::WEG)) : 0;
        wetAmt = taxByCode.exists(METConstants::WET) ? abs(taxByCode.lookup(METConstants::WET)) : 0;

        if (salesTable.SalesType == SalesType::ReturnItem)
        {
            gstAmt = -1 * gstAmt;
            wegAmt = -1 * wegAmt;
            wetAmt = -1 * wetAmt;
        }

        bundleSalesInvoiceTmp.METGSTValue  = gstAmt;
        bundleSalesInvoiceTmp.METGSTTotal  = gstAmt + wegAmt;
        bundleSalesInvoiceTmp.METWETValue  = wetAmt;
    }

    boolean isALMReport;
    // Incident 424568: WILO - Demand - WET and GST Flags and $ values incorrect on some items on PDF INV - ALM
    // For ALM and ALMExportSalesInvoice, if we have WET the GST column must be Y
    if (metSalesOrderTypes.SalesInvoiceReportDesignName == METConstants::ALM
    ||  metSalesOrderTypes.SalesInvoiceReportDesignName == METConstants::ALMExportSalesInvoice)
    {
        isALMReport = NoYes::Yes;
    }

    bundleSalesInvoiceTmp.METGST = (bundleSalesInvoiceTmp.METGSTValue != 0) ? METConstants::Y : METConstants::N;
    bundleSalesInvoiceTmp.METWET = (bundleSalesInvoiceTmp.METWETValue != 0) ? METConstants::Y : METConstants::N;


    if (isALMReport)
    {
        // Incident 424568: WILO - Demand - WET and GST Flags and $ values incorrect on some items on PDF INV - ALM
        // if there is GST or WEG, the GST flag must be Y
        bundleSalesInvoiceTmp.METGST = (bundleSalesInvoiceTmp.METGSTTotal != 0) ? METConstants::Y : METConstants::N;
        bundleSalesInvoiceTmp.METSupplierInvoiceGST =  bundleSalesInvoiceTmp.METGSTTotal;
    }

    bundleSalesInvoiceTmp.METWholesaleListPrice = _custInvoiceTrans.SalesPrice;

    if(_custInvoiceTrans.SalesUnit == 'ea')
    {
        bundleSalesInvoiceTmp.METPackQty      =   1;
        bundleSalesInvoiceTmp.METSuppliedQty  =   _custInvoiceTrans.METPickedBrokenCases;
    }
    else
    {
        bundleSalesInvoiceTmp.METPackQty      =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
        bundleSalesInvoiceTmp.METSuppliedQty  =   _custInvoiceTrans.METPickedCases;
    }

    bundleSalesInvoiceTmp.METAlcLitres        = any2Real(_custInvoiceTrans.METLitres);//get litres value

    bundleSalesInvoiceTmp.METSize             = metInventTable.ItemSize;

    str    broeknCaseFeeKey = strFmt("%1|%2", METConstants::brokenCaseFee, _custInvoiceTrans.InventTransId);
    str    deliveryFeeKey = strFmt("%1|%2", METConstants::DeliveryFee, _custInvoiceTrans.InventTransId);

    Amount brokenCaseFeeAmt = componentSums.exists(broeknCaseFeeKey) ? componentSums.lookup(broeknCaseFeeKey) : 0;
    Amount deliveryFeeAmt   = componentSums.exists(deliveryFeeKey)   ? componentSums.lookup(deliveryFeeKey)   : 0;

    bundleSalesInvoiceTmp.METDeliveryFee        = deliveryFeeAmt;
    bundleSalesInvoiceTmp.METDeliveryFeeExt     =   deliveryFeeAmt * _custInvoiceTrans.Qty;

    real uomConversion = 1.0;

    METIndustryKey parentIndustryKey = metIndustryKeyTable.ParentIndustryKey;
    boolean isBonusLine = (strScan(bundleSalesInvoiceTmp.METINDS, METConstants::BonusInd, 1, strLen(bundleSalesInvoiceTmp.METINDS)) > 0);

    if (parentIndustryKey == METConstants::ALMOrderType)// and report name alm
    {
        if (isBonusLine)
        {
            bundleSalesInvoiceTmp.METCost = 0;
            bundleSalesInvoiceTmp.METLucInclGST = (salestable.SalesType == SalesType::ReturnItem) ? bundleSalesInvoiceTmp.METLucInclGST : bundleSalesInvoiceTmp.METDeliveryFee;
            bundleSalesInvoiceTmp.METLucExclGST = 0;
            bundleSalesInvoiceTmp.METCaseCost = 0;
        }
        else
        {
            bundleSalesInvoiceTmp.METCost = this.getconversionValue(_custInvoiceTrans,salesLine, metSalesTable);
        }

        if (_custInvoiceTrans.SalesUnit == METConstants::unitEach)
        {
            uomConversion = this.getconversionValueforEA(_custInvoiceTrans);
        }
        // Sum WET, Delivery Fee, and GST first, then apply Qty division and UoM conversion
        real combinedCharges = bundleSalesInvoiceTmp.METWETValue + bundleSalesInvoiceTmp.METDeliveryFee + bundleSalesInvoiceTmp.METGSTTotal;

        real convertedCharges = (combinedCharges / _custInvoiceTrans.Qty) * uomConversion;

        // Use your new helper method if the unit is 'ea'
        if (_custInvoiceTrans.SalesUnit == METConstants::unitEach)
        {
            // Final Case Cost
            bundleSalesInvoiceTmp.metcaseCost = bundleSalesInvoiceTmp.METCost + convertedCharges + (brokenCaseFeeAmt * uomConversion);
            bundleSalesInvoiceTmp.LineAmountInclTax = (bundleSalesInvoiceTmp.metcaseCost/uomConversion) * _custInvoiceTrans.Qty;
            Amount caseGST = (bundleSalesInvoiceTmp.METGSTTotal/_custInvoiceTrans.Qty) * uomConversion;
            bundleSalesInvoiceTmp.METLucExclGST = ((bundleSalesInvoiceTmp.metcaseCost - caseGST)/_custInvoiceTrans.Qty)/uomConversion;
        }
        else
        {
            bundleSalesInvoiceTmp.metcaseCost = bundleSalesInvoiceTmp.METCost + combinedCharges + brokenCaseFeeAmt;
        }

    }
    else
    {
        // bundleSalesInvoiceTmp.METCost = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No) * _custInvoiceTrans.qty;
        bundleSalesInvoiceTmp.METCost = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No, salesLine);
    }


    bundleSalesInvoiceTmp.METRebatesFees      = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::Yes) * _custInvoiceTrans.qty;
    if (parentIndustryKey == METConstants::MFG || parentIndustryKey == METConstants::CSDCustName)
    {
        if (salestable.SalesType == SalesType::ReturnItem)
        {
            bundleSalesInvoiceTmp.METRebatesFees = -1* bundleSalesInvoiceTmp.METRebatesFees;

            LineAmount lineAmount       = abs(_custInvoiceTrans.LineAmount) + bundleSalesInvoiceTmp.METRebatesFees;
            LineAmount lineAmtInclTax   = lineAmount + abs(bundleSalesInvoiceTmp.metgstvalue);

            bundleSalesInvoiceTmp.lineAmount          = -1 * (abs(_custInvoiceTrans.LineAmount) + bundleSalesInvoiceTmp.METRebatesFees);
            bundleSalesInvoiceTmp.LineAmountInclTax   = -1 * lineAmtInclTax;
            //bundleSalesInvoiceTmp.METLucInclGST       = (lineAmtInclTax/_custInvoiceTrans.Qty)/bundleSalesInvoiceTmp.METPackQty;
            bundleSalesInvoiceTmp.METLucExclGST       = -1 * abs(_custInvoiceTrans.LineAmount + bundleSalesInvoiceTmp.METRebatesFees);
            bundleSalesInvoiceTmp.METLucInclGST       = -1 * abs(bundleSalesInvoiceTmp.METLucExclGST + bundleSalesInvoiceTmp.metgstvalue);
        }
        else
        {
            bundleSalesInvoiceTmp.lineAmount          = _custInvoiceTrans.LineAmount + bundleSalesInvoiceTmp.METRebatesFees;
            bundleSalesInvoiceTmp.LineAmountInclTax   = bundleSalesInvoiceTmp.LineAmount + bundleSalesInvoiceTmp.metgstvalue;

            if (_custInvoiceTrans.Qty && bundleSalesInvoiceTmp.METPackQty)
            {
                bundleSalesInvoiceTmp.METLucInclGST   = (bundleSalesInvoiceTmp.LineAmountInclTax/_custInvoiceTrans.Qty)/bundleSalesInvoiceTmp.METPackQty;
                bundleSalesInvoiceTmp.METLucExclGST   = (bundleSalesInvoiceTmp.LineAmount/_custInvoiceTrans.Qty)/bundleSalesInvoiceTmp.METPackQty;
            }
            else
            {
                bundleSalesInvoiceTmp.METLucInclGST   = 0;
                bundleSalesInvoiceTmp.METLucExclGST   = 0;
            }
        }
    }

    else
    {
        if (!bundleSalesInvoiceTmp.LineAmountInclTax)
        {
            bundleSalesInvoiceTmp.LineAmountInclTax   = bundleSalesInvoiceTmp.LineAmount + bundleSalesInvoiceTmp.TaxAmount;
        }
    }
    // Bug 285174 added for GST exempted items
    if(InventTable::find(_custInvoiceTrans.ItemId).metGetProductAttributeforCategory(METConstants::ConsumerGSTExempt) == "Yes")
    {
        bundleSalesInvoiceTmp.METGSTExempt = bundleSalesInvoiceTmp.LineAmountInclTax;
    }

    if(!bundleSalesInvoiceTmp.TaxAmount)// && !metMarkupTransStd.TaxAmount)
    {
        bundleSalesInvoiceTmp.METAmountTaxExempt = _custInvoiceTrans.LineAmount;//also used in CT invoice reort
    }

    bundleSalesInvoiceTmp.Name                = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( _custInvoiceTrans.ItemId).RecId, languageIdUser);

    if (metIndustryKeyTable.ParentIndustryKey == METConstants::ALMOrderType)
    {
        if (_custInvoiceTrans.SalesUnit == METConstants::unitEach && uomConversion != 0)
        {
            bundleSalesInvoiceTmp.METLucInclGST = (bundleSalesInvoiceTmp.metcaseCost * bundleSalesInvoiceTmp.Qty)/ uomConversion;
        }
        else
        {
            bundleSalesInvoiceTmp.METLucInclGST = bundleSalesInvoiceTmp.metcaseCost * bundleSalesInvoiceTmp.Qty;//salesLine.SalesQty;
        }
        // change value to -ve for return type
        if (salestable.SalesType == SalesType::ReturnItem)
        {
            METSalesLinePriceComponentTmp priceComponentTmp;

            priceComponentTmp.linkPhysicalTableInstance(METSalesPriceComponents::construct(SalesType::ReturnItem).insertTmp(salesLine));

            select firstonly priceComponentTmp
                where priceComponentTmp.PriceComponent == METPriceComponent::NetAmount;

            if (priceComponentTmp.RecId)
            {
                bundleSalesInvoiceTmp.METLucInclGST = -1 * abs(priceComponentTmp.ExtValue + bundleSalesInvoiceTmp.METWETValue + bundleSalesInvoiceTmp.METDeliveryFee + bundleSalesInvoiceTmp.METGSTTotal + brokenCaseFeeAmt);

                bundleSalesInvoiceTmp.METLucExclGST = -1 * abs(bundleSalesInvoiceTmp.METLucInclGST - bundleSalesInvoiceTmp.METGSTTotal);
            }

        }

        if(bundleSalesInvoiceTmp.Qty && bundleSalesInvoiceTmp.METPackQty)
        {
            real totalPriceExclGSTForLUC = bundleSalesInvoiceTmp.METCaseCost - bundleSalesInvoiceTmp.METGSTTotal;

            if (!bundleSalesInvoiceTmp.METLucExclGST)
            {
                bundleSalesInvoiceTmp.METLucExclGST = (totalPriceExclGSTForLUC / bundleSalesInvoiceTmp.Qty) / bundleSalesInvoiceTmp.METPackQty;
                // bundleSalesInvoiceTmp.METLucExclGST       = (totalPriceExclGST/bundleSalesInvoiceTmp.Qty)/bundleSalesInvoiceTmp.METPackQty;

                if (salestable.SalesType == SalesType::ReturnItem)
                {
                    bundleSalesInvoiceTmp.METLucExclGST = -1 * abs(bundleSalesInvoiceTmp.METLucExclGST);
                }
            }
        }
        else
        {
            bundleSalesInvoiceTmp.METLucExclGST       = 0;
        }
    }

    bundleSalesInvoiceTmp.METSupplierInvoiceAmtInclGST    = bundleSalesInvoiceTmp.LineAmountInclTax;

    //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - start.
    if (isBonusLine && metIndustryKeyTable.ParentIndustryKey == METConstants::ALMOrderType)
    {
        bundleSalesInvoiceTmp.METCaseCost = 0;
        bundleSalesInvoiceTmp.METCost = 0;
        bundleSalesInvoiceTmp.METLucInclGST = (salestable.SalesType == SalesType::ReturnItem) ? bundleSalesInvoiceTmp.METLucInclGST : bundleSalesInvoiceTmp.METDeliveryFee;
        bundleSalesInvoiceTmp.METLucExclGST = 0;
    }
    //Bug 405074 - CR - UAT - DEMAND - LIQUOR - Validate that PE Pricing - Raise a manual order in PE as a Bonus Stock Override - did not invoice correctly - end.


    if ((parentIndustryKey == METConstants::MFG || parentIndustryKey == METConstants::CSDCustName))
    {
        if (salesLine.METCWActualWeight > 0)
        {
            bundleSalesInvoiceTmp.qty = _custInvoiceTrans.PdsCWQty;
        }

        if (salesLine.METCWActualWeight == 0)
        {
            bundleSalesInvoiceTmp.METWeight = metWHSPhysDimUOMSite.NetWeight * bundleSalesInvoiceTmp.qty;
        }
        else
        {
            bundleSalesInvoiceTmp.METWeight = salesLine.METCWActualWeight;
        }
    }

    if (!bundleSalesInvoiceTmp.TaxAmount)
    {
        bundleSalesInvoiceTmp.TaxAmount = _custInvoiceTrans.TaxAmount;
    }

    bundleSalesInvoiceTmp.MCRMarkupTxt = SysLabel::labelId2String(literalStr("@SYS308474"),  _custInvoiceJour.LanguageId);

    str markupTransKey = strFmt("%1|%2", _custInvoiceTrans.TableId, _custInvoiceTrans.RecId);

    bundleSalesInvoiceTmp.MCRMarkupTxt = markupTransByInventTransId.exists(markupTransKey) ? '\n' + markupTransByInventTransId.lookup(markupTransKey) : 0;

    bundleSalesInvoiceTmp.METSalesInvoiceReportLineType   = METSalesInvoiceReportLineType::Line;


    bundleSalesInvoiceTmp.METCase = _custInvoiceTrans.METCase;

    bundleSalesInvoiceTmp.METLineNum              =   _custInvoiceTrans.LineNum;
    bundleSalesInvoiceTmp.METUnitPriceExclTax     =   _custInvoiceTrans.SalesPrice;
    bundleSalesInvoiceTmp.METUnitPriceInclTax     =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.lineAmountInclTax() / _custInvoiceTrans.Qty) : 0;
    bundleSalesInvoiceTmp.METOrderedQty           =   salesLine.SalesQty;
    bundleSalesInvoiceTmp.METUnitTax              =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
    bundleSalesInvoiceTmp.METMarginAmount         =   1;
    bundleSalesInvoiceTmp.METStandardCost         =   1;
    bundleSalesInvoiceTmp.METUnitTax              =   _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
    bundleSalesInvoiceTmp.METProductType          =   this.getItemTypeDescription(_custInvoiceTrans.METItemType);
    bundleSalesInvoiceTmp.METAlcoholCategory      =   bundleSalesInvoiceTmp.METProductType;
    bundleSalesInvoiceTmp.METSRP                  =   bundleSalesInvoiceTmp.LineAmount;
    bundleSalesInvoiceTmp.METCAT                  =   this.metGetProductAttributeforInvCategory(_custInvoiceTrans.ItemId);

    if(!bundleSalesInvoiceTmp.TaxAmount)
    {
        bundleSalesInvoiceTmp.METTaxExemptAmount = bundleSalesInvoiceTmp.LineAmount;
    }

    bundleSalesInvoiceTmp.METAlcoholContent   = metInventTable.AlcoholContent;
    bundleSalesInvoiceTmp.METCountryCode      = metInventTable.CountryCode;
    bundleSalesInvoiceTmp.METGTIN             = salesLine.BarCode;

    // Bug 418899 start
    METWHSPhysDimUOMSite metWHSPhysDimUOMSiteloc;

    select firstonly NetWeight from metWHSPhysDimUOMSiteloc
                where metWHSPhysDimUOMSiteloc.ItemId == salesline.ItemId
                && metWHSPhysDimUOMSiteloc.UOM == salesline.SalesUnit
                && metWHSPhysDimUOMSiteloc.SiteId == salesline.inventDim().InventSiteId;

    bundleSalesInvoiceTmp.metNetWeight = metWHSPhysDimUOMSiteloc.NetWeight * bundleSalesInvoiceTmp.qty;
    //Bug 418899 end 

    // === Bug 351188 - ALM invoice picked cases / broken cases logic ===
    isALMReport = (parentIndustryKey == METConstants::ALM || parentIndustryKey == METConstants::ALMExportSalesInvoice) ? true : false;
    boolean pickedCasesOrBrokenCases;

    METLegalEntityType metLegalEntityType = companyInfo.METLegalEntityType;
    if (metLegalEntityType == METLegalEntityType::Liquor && isALMReport)
    {                
        if (_custInvoiceTrans.METPickedCases)
        {
            this.metInsertPickedCaseLine(bundleSalesInvoiceTmp, _custInvoiceTrans, salesLine, _custInvoiceTrans.METPickedCases, false);
            pickedCasesOrBrokenCases = true;
        }

        if (_custInvoiceTrans.METPickedBrokenCases)
        {
            this.metInsertPickedCaseLine(bundleSalesInvoiceTmp, _custInvoiceTrans, salesLine, _custInvoiceTrans.METPickedBrokenCases, true);
            pickedCasesOrBrokenCases = true;
        }
    }

    if (!pickedCasesOrBrokenCases)
    {
        bundleSalesInvoiceList.add(bundleSalesInvoiceTmp);
    } 
}

public Map generateCachedMarkupTrans()
{
    CustInvoiceJour     custInvoiceJour;
    CustInvoiceTrans    custInvoiceTrans;
    MarkupTable         markupTable;
    MarkupTrans         markupTrans;

    markupTransByInventTransId = new Map(Types::String, Types::String);
    markupCalcAmountOnly = new Map(Types::String, Types::Real);

    select sum(CalculatedAmount), TransTableId, TransRecId, MarkupCode from markupTrans
        group by markupTrans.TransTableId, markupTrans.TransRecId, markupTrans.MarkupCode
        exists join markupTable
            where markupTable.ModuleType == markupTrans.ModuleType &&
                  markupTable.MarkupCode == markupTrans.MarkupCode &&
                  !(markupTable.VendType == MarkupType::LedgerAccount &&
                    markupTable.CustType == MarkupType::LedgerAccount)
        exists join custInvoiceTrans
            where custInvoiceTrans.TableId == markupTrans.TransTableId &&
                  custInvoiceTrans.RecId == markupTrans.TransRecId
        exists join custInvoiceJour
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId &&
                  custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId &&
                  custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate &&
                  custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup &&
                  custInvoiceJour.METShipmentId == shipmentId;
    {
        str value = markupTrans.MarkupCode + "@MET:MarkupIsEqualto" +strFmt('%1',markupTrans.CalculatedAmount);
        str key = strFmt("%1|%2", markupTrans.TransTableId, markupTrans.TransRecId);
        if (!markupTransByInventTransId.exists(key))
        {
            markupTransByInventTransId.insert(key, value);
        }

        if (!markupCalcAmountOnly.exists(key))
        {
            markupCalcAmountOnly.insert(key, markupTrans.CalculatedAmount);
        }
    }

    return markupTransByInventTransId;
}

public InventTransId getInventTransID(SalesLine _salesLine, METSalesTable metSalesTable)
{
    SalesLine     selSalesLine;
    SalesId       originalSalesId;

    // Early exit if the custom table record or OriginalInvoice reference is missing
    if (!metSalesTable || !metSalesTable.OriginalInvoice)
    {
        return '';
    }

    // Replicate the reliable mapping logic from METSalesPriceComponents_Return
    SalesTable salesTable = SalesTable::find(metSalesTable.OriginalInvoice);

    if (salesTable.RecId)
    {
        // The OriginalInvoice field contains the actual SalesId
        originalSalesId = metSalesTable.OriginalInvoice;
    }
    else
    {
        // The OriginalInvoice field contains the InvoiceId, so we must trace it back
        CustInvoiceJour custInvoiceJour;

        select firstOnly SalesId from custInvoiceJour
            order by InvoiceDate desc
            where custInvoiceJour.InvoiceId == metSalesTable.OriginalInvoice
            exists join salesTable
                where custInvoiceJour.InvoiceAccount == salesTable.CustAccount &&
                      salesTable.RecId == metSalesTable.SalesTable;

        originalSalesId = custInvoiceJour.SalesId;
    }

    // Fetch the corresponding original InventTransId based on the resolved SalesId
    if (originalSalesId)
    {
        select firstonly InventTransId from selSalesLine
            where selSalesLine.SalesId == originalSalesId
               && selSalesLine.ItemId == _salesLine.ItemId;

        return selSalesLine.InventTransId;
    }

    return '';
}

public Amount getconversionValue(CustInvoiceTrans _custInvoiceTrans, SalesLine _salesline, METSalesTable metSalesTable)
{
    InventItemSalesSetup inventItemSalesSetup;
    Inventdim inventdim;
    Real convertedValue = 1, calculatedBaseAmt;
    InventTransId targetInventTransId;

    // Determine the correct InventTransId based on SalesType
    if (_salesline.SalesType == SalesType::ReturnItem)
    {
        // Use your existing custom utility to fetch the original order's Lot ID
        targetInventTransId = this.getInventTransID(_salesline, metSalesTable);
    }
    else
    {
        targetInventTransId = _custInvoiceTrans.InventTransId;
    }

    select METSalesUnit from inventItemSalesSetup
     exists join inventdim where inventdim.inventdimid == inventItemSalesSetup.INVENTDIMID
         && inventItemSalesSetup.itemid == _custInvoiceTrans.ItemId
         && inventdim.InventSiteId == _custInvoiceTrans.inventSiteId();

    str basePriceKey = strFmt("%1|%2", METConstants::ComponentBasePrice, _custInvoiceTrans.InventTransId);
    str feeKey = strFmt("%1|%2", METConstants::ComponentMargin, _custInvoiceTrans.InventTransId);
    str discountKey = strFmt("%1|%2", METConstants::ComponentDiscount, _custInvoiceTrans.InventTransId);

    real baseVal = componentSums.exists(basePriceKey)  ? componentSums.lookup(basePriceKey)  : 0;
    real feesVal = componentSums.exists(feeKey)    ? componentSums.lookup(feeKey)    : 0;
    real discVal = componentSums.exists(discountKey)  ? componentSums.lookup(discountKey)  : 0;

    if (_custInvoiceTrans.SalesUnit == 'ea')
    {
        convertedValue =  this.getCachedConversion(_custInvoiceTrans.ItemId, inventItemSalesSetup.METSalesUnit, _custInvoiceTrans.SalesUnit);
    }

    calculatedBaseAmt = convertedValue * (baseVal + feesVal - discVal);

    return calculatedBaseAmt;
}

private void metInsertPickedCaseLine(METBundleSalesInvoiceTmp     _salesInvoiceTmpBase,
                                 CustInvoiceTrans    _custInvoiceTrans,
                                 SalesLine           _salesLine,
                                 METCase             _qty,
                                 boolean             _isBrokenCase)
{
    METBundleSalesInvoiceTmp caseLine;

    EcoResProduct product;
    RecId         caseUom;
    RecId         eaUom;

    Qty          pickedCases;
    Qty          pickedBrokenCases;
    Qty          brokenQtyInCaseUnit;
    Qty          currentQtyInCaseUnit;
    Qty          totalPickedQtyInCaseUnit;

    real         allocationFactor;

    // Copy all fields from base line - carries over ItemId, description,
    // prices, charges, tax groups, and all other mapped fields.
    caseLine.data(_salesInvoiceTmpBase);

    // Clear RecId to force a new insert rather than updating existing record.
    caseLine.RecId = 0;

    product = EcoResProduct::findByProductNumber(_salesLine.ItemId);
    caseUom = UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit);
    eaUom   = UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach);

    pickedCases       = _custInvoiceTrans.METPickedCases;
    pickedBrokenCases = _custInvoiceTrans.METPickedBrokenCases;

    // Convert broken EA quantity back to sales-line unit/case unit.
    if (pickedBrokenCases && product.RecId && caseUom && eaUom)
    {
        brokenQtyInCaseUnit = UnitOfMeasureConverter::convert(
                            pickedBrokenCases,
                            eaUom,
                            caseUom,
                            NoYes::No,
                            product.RecId,
                            NoYes::No);
    }
    else
    {
        brokenQtyInCaseUnit = 0;
    }

    // Total supplied quantity in the same unit as the original sales line.
    totalPickedQtyInCaseUnit = pickedCases + brokenQtyInCaseUnit;

    if (_isBrokenCase)
    {
        // --- Broken cases line overrides - Bug 351188 ---

        // Qty Supplied = picked broken cases value.
        caseLine.Qty = _qty;

        // UOM = EA for broken case line.
        caseLine.SalesUnitTxt = METConstants::unitEach;

        // Current line quantity in case unit for amount/GST allocation.
        currentQtyInCaseUnit = brokenQtyInCaseUnit;

        if (totalPickedQtyInCaseUnit)
        {
            allocationFactor = currentQtyInCaseUnit / totalPickedQtyInCaseUnit;
        }
        else
        {
            allocationFactor = 0;
        }

        if (currentQtyInCaseUnit > 0)
        {
            // CHANGE:
            // Cost and LUC for broken line should be based on broken quantity converted to case unit.
            //caseLine.METCost = _salesInvoiceTmpBase.METCost * currentQtyInCaseUnit;

            // Update the inserted caseLine, not the base line, because base line is deleted later.
            real uomConversion = 1.0;

            uomConversion = this.getconversionValueforEA(_custInvoiceTrans);

            caseLine.METLucInclGST = abs(_salesInvoiceTmpBase.metcaseCost/uomConversion) * currentQtyInCaseUnit;

            caseLine.METGSTTotal = abs(_salesInvoiceTmpBase.METGSTTotal * allocationFactor);
        }
        else
        {
            caseLine.METCost       = 0;
            caseLine.METLucInclGST = 0;
            caseLine.METGSTTotal   = 0;
        }

        if (caseLine.SalesUnitTxt != METConstants::unitEach)
        {
            // Qty Ordered = 0 for broken case/Not EA line.
            caseLine.METOrderedQty = 0;
        }
    }
    else
    {
        // --- Picked cases line overrides - Bug 351188 ---

        // Qty Supplied = picked cases value.
        caseLine.Qty = _qty;

        // Qty Ordered = original sales order quantity.
        caseLine.METOrderedQty = _salesLine.SalesQty;

        // UOM = original sales order/invoice unit. outer6
        caseLine.SalesUnitTxt = _custInvoiceTrans.SalesUnit;

        currentQtyInCaseUnit = caseLine.Qty;

        if (totalPickedQtyInCaseUnit)
        {
            allocationFactor = currentQtyInCaseUnit / totalPickedQtyInCaseUnit;
        }
        else
        {
            allocationFactor = 0;
        }

        // This part was already conceptually correct.
        real uomConversion = 1.0;

        if (caseLine.SalesUnitTxt == METConstants::unitEach)
        {
            uomConversion = this.getconversionValueforEA(_custInvoiceTrans);
        }

        if (caseLine.SalesUnitTxt == METConstants::unitEach && uomConversion != 0)
        {
            caseLine.METLucInclGST = abs(_salesInvoiceTmpBase.metcaseCost/uomConversion) * currentQtyInCaseUnit;
        }
        else
        {
            caseLine.METLucInclGST = abs(_salesInvoiceTmpBase.metcaseCost * currentQtyInCaseUnit);
        }

        caseLine.METGSTTotal = abs(_salesInvoiceTmpBase.METGSTTotal * allocationFactor);
    }

    bundleSalesInvoiceList.add(caseLine);
}

public void generateBundlingHeaderFooterTmp(CustInvoiceJour         _custInvoiceJour,
                                            CustTable               _custTable,
                                            METCustTable            _metCustTable,
                                            SalesTable              _salesTable,
                                            METSalesTable           _metSalesTable,
                                            METIndustryKeyTable     _metIndustryKeyTable,
                                            DirPartyTable           _dirPartyTable,
                                            METInventItemOrderSetup _metInventItemOrderSetup,
                                            METSalesOrderTypes      _metSalesOrderTypes,
                                            str1260                 headerGuid,
                                            METBundleSalesInvoiceHeaderFooterTmp bundlingHeaderFooterTmp,
                                            METBundleSalesCTInvoiceTmp metSalesCTInvoiceTmp)
{
    Map metChargesComponentMap = new Map(Types::String, Types::Real);
    METSalesLinePriceComponent  metSalesLinePriceComponent, metSalesLinePriceComponentloc;

    bundlingHeaderFooterTmp.clear();
    bundlingHeaderFooterTmp.CompanyEmail = companyInfo.email();
    bundlingHeaderFooterTmp.BundleReportHeaderGuidStr = bundlingHeaderGUID;
    bundlingHeaderFooterTmp.SalesInvoiceHeaderGuidStr = headerGuid;

    this.generateHeaderKPMGFields(bundlingHeaderFooterTmp, _custInvoiceJour);

    bundlingHeaderFooterTmp.METBranchName = inventLocation.Name;
    bundlingHeaderFooterTmp.METBranchNumber = _salesTable.InventLocationId;

    bundlingHeaderFooterTmp.METShipToPhone = shipToPhone;
    bundlingHeaderFooterTmp.METInvoiceToPhone = invoiceToPhone;

    str feeKey = strFmt("%1|%2", _custInvoiceJour.TableId, _custInvoiceJour.RecId);
    bundlingHeaderFooterTmp.METFees = Fees.exists(feeKey) ? Fees.lookup(feeKey) : 0;

    bundlingHeaderFooterTmp.METGSTActual = headerTaxTrans.exists(feeKey) ? headerTaxTrans.lookup(feeKey) : 0;

    bundlingHeaderFooterTmp.METFeesTotal = bundlingHeaderFooterTmp.METFees + bundlingHeaderFooterTmp.METGSTActual;

    bundlingHeaderFooterTmp.METInvoiceReportInternetBankingNotes = custFormLetterParameters.METInvoiceReportInternetBankingNotes;

    bundlingHeaderFooterTmp.InvoiceDate             = _custInvoiceJour.InvoiceDate;
    bundlingHeaderFooterTmp.METEFTAccountDetails    = subStr(_metCustTable.BsbReference, 1, 6);
    bundlingHeaderFooterTmp.METEFTReferenceText     = subStr(_metCustTable.BsbReference, strLen(_metCustTable.BsbReference) - 8, 9);
    bundlingHeaderFooterTmp.METStatementDate        = bundlingHeaderFooterTmp.InvoiceDate;

    bundlingHeaderFooterTmp.METBPayBillerCode       = _metCustTable.BPayBillerCode;
    bundlingHeaderFooterTmp.METBPayReference        = _metCustTable.BPayReference;
    bundlingHeaderFooterTmp.METDeliveryRoute        = _salesTable.METRoute+' / '+ int2Str(_salesTable.METRouteStopNum);
    bundlingHeaderFooterTmp.METCustGroup            = _custTable.CustGroup;
    bundlingHeaderFooterTmp.METRepCode              = _metCustTable.SalesRepCode;

    bundlingHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
    bundlingHeaderFooterTmp.METDeliverToName        = _dirPartyTable.NameAlias;

    bundlingHeaderFooterTmp.METDeliverToAddress     = _custTable.metGetDeliveryaddress();

    bundlingHeaderFooterTmp.METPaymTerms            = _salesTable.Payment;
    bundlingHeaderFooterTmp.METDueDate              = _custInvoiceJour.DueDate;
    bundlingHeaderFooterTmp.METSalesOrderType       = _salesTable.METSalesOrderType;
    bundlingHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
    bundlingHeaderFooterTmp.METInvoiceToABN         = _salesTable.VATNum;
    bundlingHeaderFooterTmp.METCustOperGroupId      = _custTable.METCustOperGroupId;
    bundlingHeaderFooterTmp.METSpecialInstruction   = _metSalesTable.DeliveryInstructions;
    bundlingHeaderFooterTmp.METCustAccount          = _salesTable.CustAccount;
    bundlingHeaderFooterTmp.METCustName             = _custTable.name();
    bundlingHeaderFooterTmp.METReturnItemNum        = _salesTable.ReturnItemNum;
    bundlingHeaderFooterTmp.SalesId                 = _salesTable.SalesId;
    bundlingHeaderFooterTmp.CustomerRef             = _custInvoiceJour.CustomerRef;
    bundlingHeaderFooterTmp.PurchaseOrder           = _custInvoiceJour.PurchaseOrder;
    bundlingHeaderFooterTmp.InvoiceAccount          = _custInvoiceJour.InvoiceAccount;
    bundlingHeaderFooterTmp.METCustTobaccoLicense   = licenceCustTobaccoMap.exists(_salesTable.SalesId) ? licenceCustTobaccoMap.lookup(_salesTable.SalesId) : "";
    bundlingHeaderFooterTmp.METCustLiquorLicense    = licenceCustLiqMap.exists(_salesTable.SalesId) ? licenceCustLiqMap.lookup(_salesTable.SalesId) : "";
    bundlingHeaderFooterTmp.METTobaccoLicense       = licenceMetcashMap.exists(_salesTable.SalesId) ? licenceMetcashMap.lookup(_salesTable.SalesId) : "";

    bundlingHeaderFooterTmp.metIndustryKey          = _metIndustryKeyTable.ParentIndustryKey;
    bundlingHeaderFooterTmp.InvoicingName           = _dirpartyTable.KnownAs;
    bundlingHeaderFooterTmp.invoicingAddress        = _custTable.invoiceAddress().Address;

    SysDocuBrandDetails docuBrandDetails = this.findByRepNameIndKeyandDesignName(METConstants::METSalesInvoice, _metSalesOrderTypes.SalesInvoiceReportDesignName, _metIndustryKeyTable.IndustryKey);

    bundlingHeaderFooterTmp.CompanyName     = _metIndustryKeyTable.CompanyName;

    if (docuBrandDetails)
    {
        bundlingHeaderFooterTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
        bundlingHeaderFooterTmp.CompanyPhone    = docuBrandDetails.Phone;
        bundlingHeaderFooterTmp.CompanyEmail    = docuBrandDetails.Email;
        bundlingHeaderFooterTmp.METNotesFooter  = docuBrandDetails.METReportNotes;
    }

    bundlingHeaderFooterTmp.METSupplierSiteNameAddress = LogisticsPostalAddress::findByLocation(InventLocation::getLocationFromRole(inventLocation.RecId, LogisticsLocationRoleType::Delivery)).Address;

    METComponentCode metComponentCode;
    SalesLine saleslineloc;

    while select sum(Value), Component from metSalesLinePriceComponent
        group by metSalesLinePriceComponent.Component
        join saleslineloc
            where saleslineloc.SalesId == _salesTable.SalesId
                && saleslineloc.InventTransId == metSalesLinePriceComponent.InventTransId
        join metComponentCode
            where metComponentCode.Component == metSalesLinePriceComponent.Component
                && metComponentCode.PriceComponent == METPriceComponent::LineCharges
    {

        if(metChargesComponentMap.exists(metSalesLinePriceComponent.Component))
        {
            metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metChargesComponentMap.lookup(metSalesLinePriceComponent.Component) + metSalesLinePriceComponent.Value);
        }
        else
        {
            metChargesComponentMap.insert(metSalesLinePriceComponent.Component, metSalesLinePriceComponent.Value);
        }
    }

    // DOMS totals
    MapEnumerator metMapEnumeratorStd;
    metMapEnumeratorStd = metChargesComponentMap.getEnumerator();
    while (metMapEnumeratorStd.moveNext())
    {
        bundlingHeaderFooterTmp.METComponentCode        += metMapEnumeratorStd.currentKey() + '\n';
        bundlingHeaderFooterTmp.METComponentVal         += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
        bundlingHeaderFooterTmp.METComponentValueTotal  +=metMapEnumeratorStd.currentValue();
    }

    MarkupTrans markupTransloc;
    MarkupTable markupTableloc;
    TaxTrans    taxTrans;
    //Header Delivery and Admin fees
    select sum(Value),MarkupCategory from markupTransloc
            where markupTransloc.TransRecId    == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
            && markupTransloc.IsDeleted == NoYes::No
            exists join markupTableloc
                where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::AdminFees;

    bundlingHeaderFooterTmp.METAdminFee = markupTransloc.Value;
    // Set symbol only if admin fee than pass the $ value
    if (markupTransloc.MarkupCategory  == MarkupCategory::Fixed)
    {
        bundlingHeaderFooterTmp.METAdminFeeSymbol = METConstants::Dollar;
    }
    else if (markupTransloc.MarkupCategory  == MarkupCategory::Percent)
    {
        bundlingHeaderFooterTmp.METAdminFeeSymbol = METConstants::Percent;
    }
    select sum(Value) from markupTransloc
        where markupTransloc.TransRecId == _custInvoiceJour.recid && markupTransloc.TransTableId  == _custInvoiceJour.TableId
            && markupTransloc.IsDeleted == NoYes::No
            exists join markupTableloc
        where markupTableloc.MarkupCode == markupTransloc.MarkupCode && markupTableloc.METChargeType == METChargeType::DeliveryFees;

    bundlingHeaderFooterTmp.METDeliveryFee = markupTransloc.Value;

    // only run for food weekly report
    TaxTrans metTaxTransStd;
    custInvoiceJour custInvoiceJourloc;
    CustInvoiceTrans custInvoiceTransloc;

    select sum(LineAmount),sum(LineAmountTax) from custInvoiceTransloc
        where custInvoiceTransloc.SalesId == _custInvoiceJour.SalesId
        && custInvoiceTransloc.numberSequenceGroup == _custInvoiceJour.numberSequenceGroup
        && custInvoiceTransloc.InvoiceId == _custInvoiceJour.InvoiceId
        && custInvoiceTransloc.InvoiceDate == _custInvoiceJour.InvoiceDate && custInvoiceTransloc.TaxItemGroup == METConstants::GSTFree;

    bundlingHeaderFooterTmp.metGSTFree = custInvoiceTransloc.LineAmount + custInvoiceTransloc.LineAmountTax;

    // Sum the tax amount in the accounting currency (TaxAmountMST)
    select sum(SourceBaseAmountCur) from taxTrans
    where taxTrans.Voucher       == _custInvoiceJour.LedgerVoucher
       && taxTrans.TransDate     == _custInvoiceJour.InvoiceDate
        && taxTrans.TaxCode == METConstants::GSTFree;

    bundlingHeaderFooterTmp.METGSTFreePosted = abs(taxTrans.SourceBaseAmountCur);

    //bug 285404 end
    bundlingHeaderFooterTmp.METRemittanceEmail      = remitEmail;

    this.metgetSalesOrderPriceComponent(bundlingHeaderFooterTmp, _custInvoiceJour);

    // for CT report
    METCBCTInvoiceHeaderTable   metCBCTInvoiceHeaderTable;
    if (CompanyInfo::find().METLegalEntityType == METLegalEntityType::Liquor)
    {
        select firstonly metCBCTInvoiceHeaderTable
        where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceJour.SalesId;

        bundlingHeaderFooterTmp.METSupplierInvoiceDate  = metCBCTInvoiceHeaderTable.DocumentDate; //supplier inv date
        bundlingHeaderFooterTmp.METSupplierInvoice      = metCBCTInvoiceHeaderTable.TaxInvoiceNum;// supplier inv no
        bundlingHeaderFooterTmp.METSupplierName         = metCBCTInvoiceHeaderTable.getVendName(); //suplier name
        bundlingHeaderFooterTmp.METVendorAccount        = metCBCTInvoiceHeaderTable.VendorAccount; //suplier Id
     }

    //Update Charge through invoice details
    if (_metSalesOrderTypes.SalesInvoiceReportDesignName == METConstants::FoodCTInvoice)
    {
        this.insertMETCTSalesInvoiceTmp(_custInvoiceJour, metSalesCTInvoiceTmp);
    }

    bundleSalesInvoiceHeaderFooterList.add(bundlingHeaderFooterTmp);
}

public LogisticsElectronicAddressLocator getRemitEmail()
{
    LogisticsElectronicAddress logisticsElectronicAddress;
    DirPartyLocation dirPartyLocation;
    Dirpartytable dirpartytable;

    select firstonly dirpartytable
        join dirPartyLocation
            where dirPartyLocation.party == dirpartytable.recid && dirpartytable.recid == companyInfo.RecId
        join logisticsElectronicAddress
            where logisticsElectronicAddress.location == dirPartyLocation.location && logisticsElectronicAddress.Description == METConstants::Remitemail;

    return logisticsElectronicAddress.locator;
}

private container getProductCategory(VendAccount _vendorAccount, METCBCTNumber _number)
    {
        METVendTable metVendTable;
        METCBCTInvoiceLine  cbcTInvoiceLine;

        select firstonly FinancialDimension from cbcTInvoiceLine
            where cbcTInvoiceLine.VendCustType == METCBCTVendCust::Vend
               && cbcTInvoiceLine.HeaderNumber == _number
            exists join metVendTable
                where metVendTable.AccountNum == _vendorAccount
                && metVendTable.ChargeThroughServiceItemId == cbcTInvoiceLine.ItemId;

        return this.getDimensionDisplayValue(cbcTInvoiceLine.FinancialDimension ,METConstants::Department);
    }

public container getDimensionDisplayValue(RecId _defaultDimension, Name _dimName)
{
    DimensionAttributeValueSetStorage dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);
    RecId attributeValueRecId = dimStorage.getValueByDimensionAttribute(DimensionAttribute::findByName(_dimName).RecId);
    DimensionAttributeValue attributeValue = DimensionAttributeValue::find(attributeValueRecId);
    DimensionFinancialTag finTag;
    DimensionAttributeDirCategory dimensionAttributeDirCategory;

    select firstonly DirCategory from dimensionAttributeDirCategory
                where dimensionAttributeDirCategory.DimensionAttribute == attributeValue.DimensionAttribute;

    finTag = DimensionFinancialTag::findByFinancialTagCategoryAndValue(dimensionAttributeDirCategory.DirCategory, attributeValue.DisplayValue);

    return [finTag.Value, finTag.Description];
}

private MarkupValue getMarkupHeaderValue(CustInvoiceJour _custInvoiceJour, METChargeType _chargeType)
{
    MarkupTrans markupTransloc;
    MarkupTable markupTableloc;

    select sum(Value) from markupTransloc
            where markupTransloc.TransRecId == _custInvoiceJour.RecId
                    && markupTransloc.TransTableId  == _custInvoiceJour.TableId
                    && markupTransloc.MarkupCategory == MarkupCategory::Percent
                exists join markupTableloc
                    where markupTableloc.MarkupCode == markupTransloc.MarkupCode

                    && markupTableloc.METChargeType == _chargeType;
    return markupTransloc.Value;
}

public void insertMETCTSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour, METBundleSalesCTInvoiceTmp metSalesCTInvoiceTmp)
{
    METCBCTInvoiceHeaderTable   metCBCTInvoiceHeaderTable;
    TaxTrans metTaxTransStd;

    while select metCBCTInvoiceHeaderTable
        where metCBCTInvoiceHeaderTable.RefSalesId == _custInvoiceJour.SalesId
    {
        metSalesCTInvoiceTmp.clear();

        metSalesCTInvoiceTmp.SupplierName           =   metCBCTInvoiceHeaderTable.getVendName(); //suplier name
        metSalesCTInvoiceTmp.VendorAccount          =   metCBCTInvoiceHeaderTable.VendorAccount; //suplier Id
        metSalesCTInvoiceTmp.TaxInvoiceNum          =   metCBCTInvoiceHeaderTable.TaxInvoiceNum;// supplier inv no
        metSalesCTInvoiceTmp.DocumentDate           =   metCBCTInvoiceHeaderTable.DocumentDate; //invoice date
        metSalesCTInvoiceTmp.VendInvoiceAmtInclGST  =   metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST;//incl GST
        metSalesCTInvoiceTmp.VendInvoiceGSTAmount   =   metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount; //GST
        metSalesCTInvoiceTmp.Number                 =   metCBCTInvoiceHeaderTable.Number;

        metSalesCTInvoiceTmp.ProdCATDimensionValue  = conPeek(this.getProductCategory(metSalesCTInvoiceTmp.VendorAccount, metCBCTInvoiceHeaderTable.Number), 1);

        metSalesCTInvoiceTmp.DiscValue1 = this.getMarkupValue(_custInvoiceJour.RecId, metCBCTInvoiceHeaderTable.Number, METChargeType::ChargeThroughDiscCode1);
        metSalesCTInvoiceTmp.Disc1Amt = -1 * abs(metSalesCTInvoiceTmp.VendInvoiceAmtInclGST * metSalesCTInvoiceTmp.DiscValue1/100); //282469 passing value as same sign as in markup setup

        metSalesCTInvoiceTmp.DiscValue2 = this.getMarkupValue(_custInvoiceJour.RecId, metCBCTInvoiceHeaderTable.Number, METChargeType::ChargeThroughDiscCode2);
        metSalesCTInvoiceTmp.Disc2Amt = -1 * abs(metSalesCTInvoiceTmp.VendInvoiceAmtInclGST * metSalesCTInvoiceTmp.DiscValue2/100);

        metSalesCTInvoiceTmp.MarginValue = this.getMarkupHeaderValue(_custInvoiceJour, METChargeType::ChargeOnChargethrough);
        metSalesCTInvoiceTmp.MarginAmt = (metSalesCTInvoiceTmp.VendInvoiceAmtInclGST + metSalesCTInvoiceTmp.Disc1Amt + metSalesCTInvoiceTmp.Disc2Amt) * metSalesCTInvoiceTmp.MarginValue/100;

        select TaxCode, sum(sourceregulateamountcur) from metTaxTransStd
            group by taxCode
            where  metTaxTransStd.TaxCode == METConstants::GST && metTaxTransStd.Voucher == _custInvoiceJour.LedgerVoucher
            && metTaxTransStd.TransDate == _custInvoiceJour.InvoiceDate;

        metSalesCTInvoiceTmp.GSTPayable = abs(metTaxTransStd.sourceregulateamountcur);

        metSalesCTInvoiceTmp.SalesUnitTxt           =   METConstants::unitEach;


        if (metSalesCTInvoiceTmp.GSTPayable)
        {
            metSalesCTInvoiceTmp.METIsGST    = METConstants::Y;
        }
        else
        {
            metSalesCTInvoiceTmp.METIsGST      = METConstants::N;
        }

        bundleSalesCTInvoiceList.add(metSalesCTInvoiceTmp);
    }
}

private MarkupValue getMarkupValue(RecId _CustInvoiceJourrecId, METCBCTNumber _cbtInvoiceNumber, METChargeType _ChargeType)
{
    MarkupTrans  markupTransloc;
    MarkupTable markupTableloc;
    SalesLine salesLineLoc;
    METSalesLine metSalesLineLoc;

    CustInvoiceTrans custInvoiceTransLoc;

    select firstonly RecId, InventTransId, TableId
            from custInvoiceTransLoc
            where custInvoiceTransLoc.ParentRecId == _CustInvoiceJourrecId;

    select sum(Value) from markupTransloc
            where markupTransloc.TransRecId == custInvoiceTransLoc.RecId
                    && markupTransloc.TransTableId  == custInvoiceTransLoc.TableId
                    && markupTransloc.MarkupCategory == MarkupCategory::Percent
                exists join markupTableloc
                    where markupTableloc.MarkupCode == markupTransloc.MarkupCode
                    && markupTableloc.METChargeType == _ChargeType
                exists join saleslineloc
                    where saleslineloc.InventTransId == custInvoiceTransLoc.InventTransId
                exists join metSalesLineloc
                    where metSalesLineloc.SalesLine == saleslineloc.RecId
                        && metSalesLineloc.CBTInvoiceNumber == _cbtInvoiceNumber;

    return markupTransloc.Value;
}

public METBundleSalesInvoiceHeaderFooterTmp metgetSalesOrderPriceComponent(METBundleSalesInvoiceHeaderFooterTmp _salesInvoiceHeaderFooterTmp, CustInvoiceJour _custInvoiceJour)
{
    METComponentCode metComponentCode;
    METSalesLinePriceComponent  metSalesLinePriceComponent;
    CustInvoiceTrans custInvoiceTrans,custInvoiceTransloc;
    CustInvoiceJour custInvoiceJour;

    // Creating a map to store and group the calculated values by component name
    Map componentTotalMap = new Map(Types::String, Types::Real);
    MapEnumerator mapEnum;
    str currentComponent;
    real calculatedLineTotal;
    real currentMapTotal;
    boolean ismdfcalculated;

    // charges eg service fee is calculated here
    while select sum(Value), InventTransId from metSalesLinePriceComponent
    group by Component,custInvoiceTrans.InventTransId
        where metSalesLinePriceComponent.Value != 0
    join metComponentCode
        where metSalesLinePriceComponent.Component == metComponentCode.Component && metComponentCode.PriceComponent == METPriceComponent::LineCharges
    join custInvoiceTrans
        where metSalesLinePriceComponent.InventTransId == custInvoiceTrans.InventTransId
            && custInvoiceTrans.InvoiceId == _custInvoiceJour.InvoiceId
    {
        // Initialized to 0 to prevent previous loop values from carrying over
        real mdfvalue = 0;

        select firstonly Qty, METActualWeight from custInvoiceTransloc
        where custInvoiceTransloc.InventTransId == custInvoiceTrans.InventTransId;

        if (metSalesLinePriceComponent.Component == METConstants::DeliveryFee && !ismdfcalculated) // for delivery add mdf value
        {
            markupTrans markupTrans;
            ismdfcalculated = true;

            select firstonly CalculatedAmount from markupTrans
        where markupTrans.TransTableId      == _custInvoiceJour.TableId
            && markupTrans.TransRecId        == _custInvoiceJour.RecId
            && markupTrans.CalculatedAmount  != 0
            && markupTrans.MarkupCode        == METConstants::MDF;

            if (markupTrans.RecId)  // only if MDF record actually found
            {
                mdfValue = markupTrans.CalculatedAmount;
            }
        }

        // Calculate the total for this specific line iteration
        currentComponent = metSalesLinePriceComponent.Component;

        // Incident 424864: WILO - Demand - Rebates/Fees Extended Details displaying incorrect values on PDF Inv - MFG
        // Handle CW items
        SalesInvoicedQty qty = custInvoiceTransloc.Qty;
        if (custInvoiceTransloc.METActualWeight)
        {
            qty = custInvoiceTransloc.METActualWeight;
        }

        calculatedLineTotal = ((metSalesLinePriceComponent.value * qty) + mdfvalue);

        // Aggregate into the Map (If it exists, add to it. If not, insert it.)
        if (componentTotalMap.exists(currentComponent))
        {
            currentMapTotal = componentTotalMap.lookup(currentComponent);
            componentTotalMap.insert(currentComponent, currentMapTotal + calculatedLineTotal);
        }
        else
        {
            componentTotalMap.insert(currentComponent, calculatedLineTotal);
        }

        // Incident 424864: WILO - Demand - Rebates/Fees Extended Details displaying incorrect values on PDF Inv - MFG
        // Handle CW items
        _salesInvoiceHeaderFooterTmp.METHeaderLineChargesTotal += metSalesLinePriceComponent.value * qty;
    }

    // Loop through the map after the while select finishes to build the final string
    mapEnum = componentTotalMap.getEnumerator();
    while (mapEnum.moveNext())
    {
        _salesInvoiceHeaderFooterTmp.METHeaderLineChargesCode  += mapEnum.currentKey() + '\n';
        _salesInvoiceHeaderFooterTmp.METHeaderLineChargesValue += strFmt('%1', mapEnum.currentValue()) + '\n';
    }
    return _salesInvoiceHeaderFooterTmp;
}
